starterCss:
body { font-family: Verdana, Geneva, sans-serif; background: #E8F3EF; color: #10332C; margin: 0; padding: 1.2rem; }
header { display: flex; align-items: center; gap: 1rem; }
header img { border-radius: 12px; background: #fff; }
h1 { margin: 0; color: #0F5C4C; font-size: 2rem; }
header p { margin: .2rem 0 0; font-style: italic; }
h2 { color: #0F5C4C; margin-top: 1.4rem; }
form { background: #fff; border: 2px solid #0F5C4C; border-radius: 12px; padding: 1rem 1.2rem; max-width: 420px; }
form p, label { display: block; margin: .9rem 0 .3rem; font-weight: bold; }
input[type="text"], input[type="email"] { width: 100%; padding: .5rem; border: 1px solid #0F5C4C; border-radius: 6px; box-sizing: border-box; font: inherit; }
.btn, button { display: inline-block; margin-top: 1rem; background: #F2B134; color: #10332C; padding: .6rem 1.2rem; border-radius: 999px; border: 0; font: inherit; font-weight: bold; cursor: pointer; }
